  id, item_type, speaker, category, title, prompt_text, short_text, full_text,
  soft_text, firm_text, clarification_text, next_action_text, avoid_text,
  diagnostic_value, red_flag_text, channel, tone, required_level, risk_level,
  source_kind, source_reference, status, version, reviewed_at
) VALUES
('ki-univ-001','question_to_client','creator','business','Что именно продаёт бизнес','Что именно Вы продаёте сейчас: отдельный товар, линейку, услугу или комплексное решение?',NULL,NULL,NULL,NULL,'Какое направление приносит основной доход или должно стать приоритетным?','Зафиксировать точный объект продвижения и не смешивать несколько задач в одном предложении.','Не переходить к формату контента, пока не понятен продукт.','Определяет предмет работы и коммерческий приоритет.',NULL,'any','neutral','required','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-002','question_to_client','creator','product','Приоритетный продукт','Какой товар или услуга сейчас важнее всего для продвижения и почему?',NULL,NULL,NULL,NULL,'Это запуск, сезонная задача, слабые продажи или новое направление?','Выбрать один приоритет для первого предложения.','Не обещать решить одновременно все направления бизнеса.','Помогает сузить задачу до управляемого проекта.',NULL,'any','neutral','required','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-003','question_to_client','creator','audience','Кто покупатель и кто принимает решение','Кто покупает продукт и кто окончательно принимает решение об оплате?',NULL,NULL,NULL,NULL,'Что для этого человека важнее всего при выборе?','Разделить пользователя, покупателя и согласующего.','Не описывать аудиторию только возрастом и полом.','Позволяет подобрать аргументы для реального лица, принимающего решение.',NULL,'any','neutral','required','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-004','question_to_client','creator','goal','Коммерческая задача','Какой конкретный результат для бизнеса должен поддержать этот контент?',NULL,NULL,NULL,NULL,'Нужны заявки, запуск, продажи конкретного товара, доверие, объяснение услуги или привлечение партнёров?','Записать одну основную задачу и один вторичный эффект.','Не заменять коммерческую задачу общими словами «красиво» и «активность».','Связывает контент с задачей бизнеса.',NULL,'any','neutral','required','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-005','question_to_client','creator','sales','Желаемое действие аудитории','Какое действие человек должен совершить после просмотра материала?',NULL,NULL,NULL,NULL,'Написать, перейти на сайт, выбрать товар, запросить расчёт, записаться или сохранить?','Привязать каждый формат к одному следующему действию.','Не ставить несколько конкурирующих призывов в одном материале.','Определяет структуру сообщения и CTA.',NULL,'any','neutral','required','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-006','question_to_client','creator','sales','Путь до оплаты','Как сейчас человек проходит путь от первого знакомства до оплаты?',NULL,NULL,NULL,NULL,'На каком этапе чаще всего появляются вопросы или пропадает интерес?','Отметить слабое место в пути клиента.','Не считать, что один визуал исправит медленный ответ или неудобное оформление заказа.','Показывает, где контент действительно может помочь.',NULL,'any','neutral','required','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-007','question_to_client','creator','content','Что уже используется','Какие материалы и форматы Вы уже используете и что из этого даёт лучший отклик?',NULL,NULL,NULL,NULL,'Есть ли статистика, сохранения, заявки или примеры публикаций, которые считаете удачными?','Сохранить сильные элементы и не начинать стратегию с нуля без причины.','Не оценивать эффективность только по личному вкусу.','Помогает опереться на реальные сигналы.',NULL,'any','neutral','recommended','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-008','question_to_client','creator','sources','Доступные исходники','Какие исходники уже есть: фотографии, видео, упаковка, логотип, брендбук, тексты и характеристики?',NULL,NULL,NULL,NULL,'Насколько актуальны и качественны эти материалы?','Определить, что можно использовать и что нужно создать заново.','Не называть точную стоимость до оценки критичных исходников.','Влияет на сложность, сроки и точность результата.',NULL,'any','neutral','required','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-009','question_to_client','creator','timeline','Срок и причина дедлайна','К какой дате нужен результат и с каким событием связан срок?',NULL,NULL,NULL,NULL,'Есть ли дата запуска, рекламной кампании, поставки или мероприятия?','Проверить реалистичность графика и время согласований.','Не подтверждать срочный срок до проверки объёма и исходников.','Отделяет реальный дедлайн от пожелания «как можно быстрее».',NULL,'any','neutral','required','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-010','question_to_client','creator','budget','Бюджетный ориентир','Какой бюджет или диапазон Вы рассматриваете для этой задачи?',NULL,NULL,NULL,NULL,'Нужно предложить тестовый формат, основной пакет или системное решение?','Сопоставить бюджет с приоритетом и сократить объём при необходимости.','Не снижать цену без изменения состава работы.','Помогает подобрать реалистичный формат.',NULL,'any','neutral','recommended','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-011','question_to_client','creator','process','Кто согласует проект','Кто будет согласовывать концепцию, тексты и финальные материалы?',NULL,NULL,NULL,NULL,'Можно ли назначить одного ответственного, который соберёт комментарии команды?','Зафиксировать ответственного и порядок согласования.','Не принимать противоречивые комментарии от разных людей как один этап правок.','Снижает задержки и хаотичные правки.',NULL,'any','neutral','required','normal','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-012','question_to_client','creator','rights','Площадки и права использования','Где будут использоваться материалы: органические соцсети, сайт, маркетплейсы, платная реклама или печать?',NULL,NULL,NULL,NULL,'Нужны ли дополнительные размеры, языки или передача материалов партнёрам?','Включить нужные адаптации и права в расчёт до старта.','Не считать расширенное рекламное использование автоматически включённым.','Определяет объём адаптаций и права использования.',NULL,'any','neutral','required','elevated','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-013','question_to_client','creator','privacy','Ограничения и конфиденциальность','Есть ли сведения, людей, документы или части проекта, которые нельзя показывать или использовать в портфолио?',NULL,NULL,NULL,NULL,'Нужно ли обезличить кейс или полностью исключить публикацию?','Зафиксировать границы хранения и публикации до получения материалов.','Не использовать переписки, данные клиентов или закрытые результаты без согласия.','Защищает приватные данные и репутацию сторон.','Клиент передаёт чувствительные данные без необходимости или просит скрыть незаконные действия.','any','neutral','required','high','manual','Универсальное ядро диагностики','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-014','question_from_client','client','price','Почему так дорого','Почему работа стоит столько, если изображения или видео создаются нейросетью?','Стоимость формируется не за нажатие кнопки, а за идею, подготовку, точное сохранение продукта, создание и отбор сцен, монтаж, согласование и подготовку результата под задачу бренда.','В проект входит анализ задачи, разработка концепции, работа с референсами, несколько итераций генерации, контроль деталей, монтаж или дизайн, правки и адаптация под площадки. Нейросеть ускоряет отдельные операции, но не заменяет профессиональное решение и ответственность за итог.','Понимаю этот вопрос. Со стороны может казаться, что нейросеть делает всё автоматически, но основная работа находится в подготовке, отборе, контроле точности и сборке результата под Ваш продукт.','Цена относится к согласованному объёму и производственному процессу. Для уменьшения бюджета нужно уменьшить количество материалов, сложность или число форматов.','Какой объём и площадки использования Вы сейчас рассматриваете?','Уточнить задачу и показать тестовый, основной и системный варианты.','Не оправдываться, не обесценивать работу и не обещать окупаемость.','Помогает объяснить ценность процесса, а не инструмента.',NULL,'any','warm','recommended','normal','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-015','question_from_client','client','timeline','Сколько времени занимает работа','Сколько времени займёт проект?','Срок зависит от объёма, сложности, качества исходников и скорости согласования. После уточнения задачи я фиксирую этапы и конкретный рабочий срок.','Сначала согласовываются задача, состав и исходники. Затем я называю срок производства и отдельно учитываю время, когда проект ожидает обратную связь клиента. Если появляются новые сцены или меняется концепция, срок пересматривается.','После короткой диагностики смогу назвать реалистичный срок без завышенных обещаний.','Точный срок подтверждается только после согласования объёма, исходников и ответственного за правки.','К какой дате нужен результат и чем обусловлен дедлайн?','Проверить календарь и зафиксировать график в КП.','Не говорить «сделаю быстро» до оценки проекта.','Управляет ожиданиями по производству и согласованиям.',NULL,'any','neutral','recommended','normal','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-016','question_from_client','client','revisions','Сколько правок входит','Сколько правок входит в стоимость?','В стоимость входит согласованное количество этапов правок. Исправление детали внутри утверждённой концепции считается правкой, а новая идея, новый продукт или новые сцены — изменением задачи.','До старта мы фиксируем число этапов правок и что именно считается правкой. Комментарии лучше собирать одним списком от ответственного лица. Дополнительные этапы или изменение утверждённой концепции рассчитываются отдельно.','Я заранее обозначаю границы, чтобы процесс был понятным для обеих сторон.','Количество правок относится к согласованной задаче. Полная смена концепции не входит в обычный этап правок.','Кто будет собирать и передавать итоговые комментарии?','Внести количество этапов и правила правок в КП.','Не обещать неограниченные правки.','Предотвращает бесконечное изменение объёма.',NULL,'any','neutral','required','normal','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-017','question_from_client','client','guarantees','Гарантия продаж и охватов','Вы можете гарантировать продажи, заявки или вирусные просмотры?','Гарантировать продажи или охваты нельзя, потому что результат зависит не только от контента, но и от продукта, предложения, цены, площадки, рекламы, обработки обращений и поведения аудитории.','Я отвечаю за согласованный состав, качество исполнения, точность материалов и соответствие выбранной стратегии. Эффективность оценивается по заранее выбранным метрикам, но конкретное число продаж или просмотров не обещается.','Можно определить реалистичные критерии оценки и посмотреть, как контент влияет на путь клиента.','Гарантии продаж, охватов и тендеров не входят в услугу и не могут быть честно обещаны.','Какие показатели Вы сейчас отслеживаете и что будет считаться полезным результатом?','Согласовать измеримые, но не гарантированные метрики.','Не придумывать проценты роста и не обещать вирусность.','Отделяет ответственность за производство от факторов бизнеса.','Клиент требует фиктивную гарантию результата или просит указать её в рекламе.','any','firm','required','high','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-018','question_from_client','client','ai','Точность товара в AI','Сможет ли AI полностью сохранить мой товар, логотип и надписи?','Я работаю по точным референсам и отдельно контролирую форму, пропорции, цвет, логотип и ключевые надписи. При этом AI может создавать искажения, поэтому результат проходит проверку, а критичные детали при необходимости дорабатываются.','До начала работы мы определяем, какие элементы нельзя изменять. Для упаковки, оборудования, маркировки и других важных деталей нужны качественные фотографии. Концептуальные сцены не должны выдаваться за документально точное изображение, если точность не подтверждена.','Чем лучше исходники и понятнее список неизменяемых деталей, тем надёжнее можно контролировать результат.','Абсолютную безошибочность генеративной модели обещать нельзя. Финальный материал утверждается после проверки клиента.','Какие элементы продукта являются критичными и кто проверит финальную точность?','Создать чек-лист неизменяемых деталей и назначить проверяющего.','Не скрывать риск искажений и не выдавать концепт за точную модель.','Устанавливает честные границы AI-производства.','Клиент просит намеренно изменить маркировку, характеристики или происхождение товара.','any','neutral','required','elevated','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-019','question_from_client','client','sources','Какие исходники нужны','Можно ли начать с фотографий, снятых на телефон?','Да, если фотографии резкие, сделаны при ровном свете и показывают товар с нужных сторон. Сначала я проверяю исходники и сообщаю, подходят ли они для точной работы.','Для предметного AI-контента особенно важны фронтальный вид, боковые ракурсы, детали упаковки, логотип, маркировка и цвет. Если исходники слабые, можно отдельно подготовить новые фотографии или скорректировать объём задачи.','Можно прислать имеющиеся материалы на предварительную проверку.','Старт по неподходящим исходникам не гарантирует точность и может потребовать отдельной подготовки.','Есть ли фотографии всех сторон товара и крупные кадры надписей?','Провести проверку исходников до расчёта финальной сложности.','Не подтверждать качество, не увидев материалы.','Определяет готовность проекта к старту.',NULL,'any','warm','recommended','normal','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-020','question_from_client','client','rights','Использование в платной рекламе','Можно ли использовать готовые материалы в платной рекламе?','Да, если рекламное использование включено в согласованные права и это отражено в предложении.','Органические публикации, сайт, маркетплейсы, платная реклама и расширенная передача партнёрам могут иметь разный объём адаптаций и прав. Площадки использования лучше зафиксировать до старта, чтобы корректно рассчитать проект.','Уточним площадки заранее и включим нужный вариант использования.','Платная реклама не считается автоматически включённой, если она не была согласована.','На каких площадках и в каких странах планируется размещение?','Зафиксировать права и нужные форматы в КП.','Не оставлять права использования неопределёнными.','Влияет на объём и стоимость проекта.',NULL,'any','neutral','required','elevated','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-021','question_from_client','client','privacy','Публикация проекта в портфолио','Вы будете публиковать нашу работу в портфолио?','Публикация обсуждается заранее. При необходимости проект можно не показывать, показать после запуска или оформить как обезличенный кейс.','Я не публикую закрытые материалы, переписку, данные клиентов и коммерческие сведения без согласования. Условия портфолио лучше указать до начала работы.','Можно выбрать подходящий уровень конфиденциальности для проекта.','Без согласия закрытые материалы не публикуются.','Нужно полностью исключить публикацию или достаточно отложить её до запуска?','Зафиксировать режим конфиденциальности в условиях.','Не использовать молчание клиента как согласие на публикацию.','Защищает приватность и ожидания клиента.',NULL,'any','warm','recommended','elevated','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-022','objection_response','creator','price','Ответ на просьбу сделать дешевле','Можно дешевле?','Снизить бюджет можно через изменение объёма: выбрать один приоритетный продукт, уменьшить число сцен или форматов либо начать с оплачиваемого теста.','Я не уменьшаю стоимость без изменения состава, потому что это скрыто сокращает качество или время работы. Вместо случайной скидки предлагаю выбрать минимальный формат, который всё ещё решает главную задачу.','Давайте сохраним главное и сократим только второстепенный объём.','Для меньшей стоимости нужно уменьшить объём или права использования.','Какой результат для Вас критичен, а что можно перенести на следующий этап?','Пересобрать пакет, а не просто уменьшить цену.','Не давать скидку в обмен на тот же объём и не оправдываться.','Сохраняет ценность и прозрачность предложения.',NULL,'any','firm','recommended','normal','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-023','question_from_client','client','quality','Что будет, если результат не понравится','Что делать, если мне не понравится результат?','До производства мы согласовываем задачу, направление и референсы. Затем правки вносятся в рамках утверждённой концепции и согласованного количества этапов.','Риск несовпадения ожиданий снижается через диагностику, мудборд или тестовый кадр, список неизменяемых деталей и поэтапное согласование. Субъективное желание полностью сменить уже утверждённое направление считается новой задачей.','Для начала можно согласовать небольшой тестовый этап, чтобы проверить направление.','Работа оценивается по согласованному заданию, а не по незафиксированному ожиданию.','Что именно для Вас определяет удачный результат: атмосфера, точность продукта, премиальность или рекламная задача?','Зафиксировать критерии приёмки и при необходимости предложить тест.','Не обещать вернуть всю оплату только из-за смены вкусового предпочтения.','Переводит субъективное ожидание в критерии.',NULL,'any','neutral','recommended','normal','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-024','ethical_rule','system','ethics','Не придумывать факты о бизнесе',NULL,'Нельзя создавать вымышленные свойства, сертификаты, клиентов, отзывы, мощности, состав, происхождение, результаты или гарантии.','AI может помогать визуализировать подтверждённую информацию, но не должен использоваться для создания ложных доказательств. Все критичные характеристики и формулировки проверяются клиентом или назначенным специалистом.',NULL,NULL,'Кто подтвердит факты и финальные формулировки?','При отсутствии подтверждения исключить утверждение или отказаться от проекта.','Не маскировать выдумку словами «концепция», если материал используется как доказательство.','Общая этическая граница всех ниш.','Клиент просит подделать документ, отзыв, результат, статус или происхождение.','any','firm','required','refusal','manual','Универсальные этические правила','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-025','red_flag','system','ethics','Запрос на фиктивные документы или кейсы',NULL,'Основание для отказа: просьба создать несуществующий сертификат, отзыв, диплом, клиента, результат, производство или иной ложный факт.','Такой запрос нельзя выполнять частично или маскировать художественной подачей. Допустима только явно обозначенная концептуальная визуализация, которая не выдаётся за реальное доказательство.',NULL,NULL,'Материал будет прямо обозначен как концепция и не станет использоваться для подтверждения факта?','Отказаться, если задача остаётся вводящей в заблуждение.','Не предлагать обходные формулировки.','Позволяет быстро остановить неподходящий проект.','Высокий риск обмана аудитории и репутационного ущерба.','any','firm','required','refusal','manual','Универсальные этические правила','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-026','follow_up','creator','communication','Повторное сообщение после молчания','Здравствуйте. Возвращаюсь к нашему разговору о [задача]. Подскажите, вопрос ещё актуален или приоритеты изменились? Если проект пока отложен, я просто отмечу это у себя и не буду отвлекать.','Здравствуйте. Подскажите, задача по [направление] ещё актуальна или пока отложена?','Сообщение напоминает о контексте, даёт простой выбор и не создаёт давления. Если ответа нет после разумного количества попыток, контакт переводится в отложенные.',NULL,NULL,NULL,'Обновить статус и дату следующего контакта либо закрыть диалог.','Не писать ежедневно, не вызывать чувство вины и не создавать ложную срочность.','Возвращает разговор уважительно и сохраняет границы.',NULL,'any','warm','recommended','normal','manual','Библиотека сценариев','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-027','first_message','creator','communication','Первое сообщение после аудита','Здравствуйте. Изучила Ваш [профиль/сайт/каталог]. Видно, что [конкретная сильная сторона], но новому клиенту сейчас непросто быстро понять [конкретный пробел]. Я помогаю упаковать такие задачи через AI-визуал, видео и понятные материалы для продажи. Какое направление у Вас сейчас приоритетно?','Здравствуйте. Изучила Ваш профиль: сильная сторона — [факт], а точка роста — [наблюдение]. Какое направление сейчас приоритетно?','Сообщение строится только на реальном наблюдении: сильная сторона, конкретный пробел, релевантная ценность и один вопрос. Оно не должно звучать как массовая рассылка.',NULL,NULL,NULL,'Если клиент отвечает, перейти к короткой диагностике.','Не начинать с критики, комплимента без факта или длинной презентации своих услуг.','Создаёт персональный первый контакт.',NULL,'instagram','warm','recommended','normal','manual','Библиотека сценариев','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-028','first_message','creator','communication','Отправка персонального КП','Спасибо за ответы. Я собрала предложение под задачу [задача]: в нём зафиксированы текущая ситуация, рекомендуемый формат, состав материалов, этапы, сроки и стоимость. Основным считаю вариант [пакет], потому что он закрывает [барьер]. После просмотра можно обсудить вопросы и при необходимости скорректировать объём, а не цель проекта.','Подготовила предложение под Вашу задачу. Основным рекомендую [пакет], потому что он решает [барьер]. После просмотра обсудим вопросы и объём.','КП отправляется с коротким пояснением логики выбора, а не как безличный файл с ценой.',NULL,NULL,'Когда Вам будет удобно вернуться с обратной связью?','Запланировать конкретную дату повторного контакта.','Не отправлять КП без резюме и не просить «посмотрите как-нибудь».','Помогает клиенту понять рекомендацию и следующий шаг.',NULL,'any','warm','recommended','normal','manual','Библиотека сценариев','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-029','question_from_client','client','trust','Опыт и портфолио','Вы уже работали с нашей нишей?','Я покажу релевантные примеры по задаче и объясню, какие решения из них применимы к Вашему проекту. Наличие точного совпадения по нише важно не всегда — важнее понимание продукта, аудитории и ограничений.','Если прямой кейс есть, он показывается без преувеличения результатов. Если нет, честно объясняется релевантный опыт, процесс исследования и возможный тестовый этап.','Могу показать примеры, близкие по задаче, визуальному уровню и формату использования.','Я не буду приписывать себе несуществующий кейс. При отсутствии прямого примера предложу ограниченный тестовый этап.','Что для Вас важнее в примере: ниша, визуальный стиль, формат или коммерческая задача?','Показать 1–3 релевантных кейса либо предложить оплачиваемый тест.','Не придумывать клиентов, цифры и результаты.','Поддерживает доверие без ложного авторитета.',NULL,'any','neutral','recommended','normal','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-univ-030','question_from_client','client','timeline','Срочный проект','Можно сделать срочно?','Срочный формат возможен только после проверки объёма, исходников и текущей загрузки. Приоритетная работа влияет на график и рассчитывается отдельно.','Сначала определяется минимальный состав, который реально выполнить к дедлайну. Срок учитывает не только производство, но и скорость передачи исходников и согласования со стороны клиента.','Проверю задачу и предложу реалистичный объём к нужной дате.','Срочность не отменяет этапы проверки и не гарантируется до согласования материалов.','Что обязательно должно быть готово к дате, а что можно передать вторым этапом?','Сократить объём, применить коэффициент срочности и зафиксировать график.','Не обещать невозможный срок ради получения заказа.','Помогает безопасно пересобрать срочную задачу.',NULL,'any','firm','recommended','elevated','manual','Универсальное ядро ответов','approved',1,'2026-08-05T00:00:00Z'),
('ki-cos-001','question_to_client','creator','claims','Подтверждённые свойства косметического продукта','Какие свойства продукта подтверждены маркировкой, составом или документами и могут использоваться в рекламе?',NULL,NULL,NULL,NULL,'Кто со стороны бренда проверит финальные формулировки?','Составить список допустимых утверждений до разработки текста и визуальных метафор.','Не превращать ассоциацию с уходом в лечебное обещание.','Отделяет подтверждённые факты от желаемых рекламных формулировок.','Клиент просит придумать лечебный, омолаживающий или гарантированный эффект.','any','neutral','required','high','manual','Пилотная ниша: косметика','approved',1,'2026-08-05T00:00:00Z'),
('ki-cos-002','question_to_client','creator','accuracy','Неизменяемые элементы упаковки','Какие элементы упаковки нельзя изменять: форма, крышка, цвет, логотип, этикетка, объём, язык или служебные обозначения?',NULL,NULL,NULL,NULL,'Есть ли актуальные фотографии всех сторон и крупные кадры текста?','Создать чек-лист точности для каждой модели или SKU.','Не считать мелкие надписи второстепенными, если материал используется в рекламе.','Определяет требования к предметной точности.','Клиент разрешает показывать упаковку с неверной маркировкой как реальную.','any','neutral','required','elevated','manual','Пилотная ниша: косметика','approved',1,'2026-08-05T00:00:00Z'),
('ki-cos-003','question_to_client','creator','product','Состав и вариант продукта','Какая точная версия продукта участвует в проекте и совпадают ли состав, объём и дизайн упаковки с актуальной продажей?',NULL,NULL,NULL,NULL,'Есть ли старые фотографии упаковки, которые нельзя использовать?','Привязать каждый материал к конкретному актуальному SKU.','Не смешивать разные версии продукта в одной карточке.','Предотвращает рекламу устаревшей или другой версии.',NULL,'any','neutral','required','elevated','manual','Пилотная ниша: косметика','approved',1,'2026-08-05T00:00:00Z'),
('ki-cos-004','question_to_client','creator','visual','Текстуры и макро','Какие реальные текстуры продукта нужно показать: крем, гель, сыворотку, пену, масло или другую консистенцию?',NULL,NULL,NULL,NULL,'Есть ли фотографии самой текстуры при дневном или студийном свете?','Выбрать макро-сцены, которые соответствуют реальной консистенции.','Не показывать продукт густым, прозрачным или цветным, если он выглядит иначе.','Связывает эстетический макро-кадр с реальным продуктом.',NULL,'any','neutral','recommended','normal','manual','Пилотная ниша: косметика','approved',1,'2026-08-05T00:00:00Z'),
('ki-cos-005','ethical_rule','system','claims','До и после для косметики',NULL,'До и после нельзя создавать или усиливать с помощью AI как доказательство результата продукта.','Допустима только честная документальная подача с необходимыми согласиями, одинаковыми условиями съёмки и проверкой допустимости формулировок. AI-концепт не должен выглядеть как реальный результат применения.',NULL,NULL,'Материал является реальным документальным сравнением и разрешён к использованию?','Исключить вымышленное сравнение или заменить его объяснением продукта и процесса использования.','Не ретушировать результат так, чтобы менялась доказательная ценность.','Предотвращает вводящую в заблуждение демонстрацию эффекта.','Запрос на создание несуществующего результата или изменение внешности для доказательства действия.','any','firm','required','refusal','manual','Пилотная ниша: косметика','approved',1,'2026-08-05T00:00:00Z'),
('ki-cos-006','ethical_rule','system','claims','Медицинские обещания в косметике',NULL,'Косметический визуал и текст не должны обещать лечение, диагностику, гарантированное избавление от состояния или результат, которого нет в подтверждённых данных.','Слова, связанные с медицинским эффектом, клиническими результатами, безопасностью и гипоаллергенностью, используются только после подтверждения и проверки ответственным специалистом клиента.',NULL,NULL,'Каким документом подтверждается формулировка и кто её утверждает?','Удалить неподтверждённое утверждение или остановить проект при намеренном обмане.','Не заменять прямое обещание намёком, который создаёт то же ложное впечатление.','Определяет границу между эстетикой и медицинским заявлением.','Клиент просит выдать косметику за лечение или скрыть отсутствие подтверждения.','any','firm','required','refusal','manual','Пилотная ниша: косметика','approved',1,'2026-08-05T00:00:00Z'),
('ki-cos-007','audit_check','system','audit','Проверка косметического бренда перед контактом',NULL,'Проверить, понятны ли назначение продукта, целевая аудитория, актуальная упаковка, ключевые свойства, путь заказа и различия между товарами линейки.','Во время аудита также отмечаются качество исходников, единый визуальный язык, наличие предметных и макро-кадров, корректность заявлений, отзывы и логика перехода к покупке.',NULL,NULL,NULL,'Сформулировать одно конкретное наблюдение для первого сообщения.','Не делать выводы о составе, безопасности и эффективности только по визуалу профиля.','Даёт основу персонального первого контакта.',NULL,'instagram','neutral','required','normal','manual','Пилотная ниша: косметика','approved',1,'2026-08-05T00:00:00Z'),
('ki-cos-008','question_from_client','client','accuracy','AI изменит этикетку','Нейросеть не испортит этикетку и надписи?','Риск искажения есть, поэтому этикетка и ключевые надписи проверяются отдельно. Для точной работы нужны крупные референсы, а финальный кадр проходит ручной контроль.','В зависимости от задачи упаковка может собираться с использованием исходного изображения, контролируемой генерации и последующей доработки. Я заранее отмечаю элементы, которые нельзя изменять, и передаю результат на проверку бренду.','Мы отдельно зафиксируем все критичные детали упаковки и проверим их перед финальной передачей.','Абсолютную точность без качественных референсов и проверки обещать нельзя.','Какие надписи и обозначения особенно важны для рекламы и продажи?','Запросить крупные исходники и создать чек-лист проверки.','Не скрывать исправления и не оставлять нечитаемый псевдотекст.','Объясняет процесс контроля точности.',NULL,'any','neutral','required','elevated','manual','Пилотная ниша: косметика','approved',1,'2026-08-05T00:00:00Z'),
('ki-cos-009','question_to_client','creator','content','Площадки косметического контента','Где будет использоваться серия: профиль бренда, карточка товара, маркетплейс, сайт, рассылка или платная реклама?',NULL,NULL,NULL,NULL,'Нужны ли версии без текста, макро, общий продуктовый кадр и рекламные адаптации?','Собрать матрицу кадров по назначению, а не просто набор эстетичных изображений.','Не использовать один кадр для всех площадок без проверки композиции и требований.','Определяет состав серии и форматы.',NULL,'any','neutral','required','normal','manual','Пилотная ниша: косметика','approved',1,'2026-08-05T00:00:00Z'),
('ki-cos-010','first_message','creator','communication','Первое сообщение косметическому бренду','Здравствуйте. Изучила Ваш профиль: продукт и упаковка выглядят узнаваемо, но новому покупателю сейчас непросто увидеть текстуру, сценарий использования и различия между позициями линейки. Я создаю точные AI-визуалы и ролики для товарных брендов, сохраняя упаковку и подтверждённые свойства. Какой продукт у Вас сейчас приоритетен?','Здравствуйте. У Вас узнаваемый продукт, но в контенте пока мало показаны текстура и различия линейки. Какой продукт сейчас приоритетен?','Перед отправкой заменить общие слова конкретным наблюдением по реальному аккаунту. Упоминать точность упаковки только как рабочий процесс, а не абсолютную гарантию.',NULL,NULL,NULL,'При ответе перейти к вопросам об актуальном SKU, исходниках и коммерческой задаче.','Не утверждать, что контент «не продаёт», и не критиковать качество продукта.','Адаптирует общий сценарий под косметическую нишу.',NULL,'instagram','warm','recommended','normal','manual','Пилотная ниша: косметика','approved',1,'2026-08-05T00:00:00Z');

-- Универсальные записи применимы ко всем нишам без дублирования текста.
INSERT OR IGNORE INTO knowledge_item_niches (knowledge_item_id, niche_id, relevance)
SELECT ki.id, n.id, 'secondary'
FROM knowledge_items ki
CROSS JOIN niches n
WHERE ki.id LIKE 'ki-univ-%';

INSERT OR IGNORE INTO knowledge_item_niches (knowledge_item_id, niche_id, relevance)
SELECT ki.id, 'niche-cosmetics', 'primary'
FROM knowledge_items ki
WHERE ki.id LIKE 'ki-cos-%';

